package com.queryx.database.entities;
import jakarta.persistence.*; import java.time.OffsetDateTime; import java.util.UUID;
@Entity @Table(name="regional_events") public class RegionalEvent { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(name="event_code",nullable=false,unique=true,length=50) private String eventCode; @Column(nullable=false,length=100) private String region; @Column(name="event_type",nullable=false,length=50) private String eventType; @Column(nullable=false,length=200) private String title; private String description; @Column(name="starts_at",nullable=false) private OffsetDateTime startsAt; @Column(name="ends_at") private OffsetDateTime endsAt; @Column(name="created_at",nullable=false) private OffsetDateTime createdAt; public UUID getId(){return id;} public String getEventCode(){return eventCode;} public void setEventCode(String v){eventCode=v;} public String getRegion(){return region;} public void setRegion(String v){region=v;} }
